var fileInput = document.getElementById('file');
if (fileInput) {
  fileInput.addEventListener('change', function (e) {
    var f = e.target.files[0]; if (!f) return; var r = new FileReader();
    r.onload = function () {
      var img = document.getElementById('photoImg');
      var card = document.getElementById('photo');
      if (img) img.src = r.result;
      if (card) card.classList.add('has');
    };
    r.readAsDataURL(f);
  });
}
var hd = document.querySelector('header');
function setH() { document.documentElement.style.setProperty('--h', hd.offsetHeight + 'px'); }
setH(); addEventListener('resize', setH);
var links = document.querySelectorAll('nav a');
var io = new IntersectionObserver(function (es) {
  es.forEach(function (en) {
    if (en.isIntersecting) { links.forEach(function (a) { a.classList.toggle('on', a.getAttribute('href') === '#' + en.target.id); }); }
  });
}, { threshold: 0.55 });
document.querySelectorAll('.slide').forEach(function (s) { io.observe(s); });

/* Module viewer: put each PDF in a 'pdfs' folder next to this file */
var MODS = [
  { t: 'Introduction to Data Science', pdf: 'pdfs/module1.pdf' },
  { t: 'Python for Data Science', pdf: 'pdfs/module2.pdf' },
  { t: 'Data Visualization and EDA', pdf: 'pdfs/module3.pdf' },
  { t: 'Machine Learning Basics', pdf: 'pdfs/module4.pdf' },
  { t: 'Big Data and Deployment', pdf: 'pdfs/module5.pdf' }];
var side = document.getElementById('sideList'), frame = document.getElementById('frame'), cur = 0, picked = {};
MODS.forEach(function (m, i) {
  var li = document.createElement('li');
  li.innerHTML = '<a href="#/module/' + (i + 1) + '">Module ' + (i + 1) + '<small>' + m.t + '</small></a>'; side.appendChild(li);
});
function show(i) {
  cur = i; var m = MODS[i];
  document.getElementById('vt').textContent = 'Module ' + (i + 1) + ': ' + m.t;
  document.getElementById('vp').textContent = picked[i] ? 'Showing the PDF you opened' : 'File: ' + m.pdf;
  frame.src = picked[i] || m.pdf;
  side.querySelectorAll('a').forEach(function (a, k) { a.classList.toggle('on', k === i); });
}
document.getElementById('pdfFile').addEventListener('change', function (e) {
  var f = e.target.files[0]; if (!f) return; picked[cur] = URL.createObjectURL(f); show(cur);
});
function route() {
  var m = location.hash.match(/^#\/module\/(\d)$/), v = !!m && MODS[m[1] - 1];
  var x = location.hash.match(/^#\/exp\/(\d)(?:\/(\d))?$/), vx = !!x && !!EXPS[x[1] - 1];
  var b = document.body.classList; b.toggle('view', v); b.toggle('viewx', vx);
  document.documentElement.classList.toggle('noSnap', v || vx);
  if (v) { window.scrollTo(0, 0); show(m[1] - 1); }
  else if (vx) { window.scrollTo(0, 0); showExp(x[1] - 1, x[2] ? x[2] - 1 : 0); }
  else if (location.hash.length > 1) { var el = document.querySelector(location.hash); if (el) el.scrollIntoView(); }
  setH();
}
