var xCur = [0, 0], xBox = document.getElementById('xCells');
function showExp(e, k) {
  xCur = [e, k]; var ex = EXPS[e], sec = ex.secs[k];
  var ul = document.getElementById('xSide'); ul.innerHTML = '';
  EXPS.forEach(function (q, i) {
    var li = document.createElement('li');
    li.innerHTML = '<a href="#/exp/' + (i + 1) + '" class="' + (i === e ? 'on' : '') + '">Exp ' + (i + 1) + '<small>' + q.t + '</small></a>';
    if (i === e && q.secs.length > 1) {
      var u = document.createElement('ul');
      q.secs.forEach(function (s2, j) {
        var l2 = document.createElement('li');
        l2.innerHTML = '<a href="#/exp/' + (i + 1) + '/' + (j + 1) + '" class="' + (j === k ? 'on' : '') + '">' + s2.id + ' ' + s2.t + '</a>'; u.appendChild(l2);
      });
      li.appendChild(u);
    }
    ul.appendChild(li);
  });
  document.getElementById('xT').textContent = 'Experiment ' + (e + 1) + ': ' + ex.t;
  document.getElementById('xD').textContent = sec.id + ' - ' + sec.t;
  document.getElementById('xF').textContent = 'EXP-' + sec.id + '.ipynb';
  document.getElementById('xC').textContent = sec.cells.length + ' cells \u00b7 saved outputs from the executed notebook';
  xBox.innerHTML = '';
  sec.cells.forEach(function (c, i) {
    var d = document.createElement('div'); d.className = 'cell';
    d.innerHTML = '<div class="n">[' + (i + 1) + ']</div><div><textarea spellcheck="false" aria-label="Code cell ' + (i + 1) + '"></textarea><div class="run"><button class="btn2">&#9655; Run</button><span>Shift + Enter</span></div><div class="out"></div></div>';
    var ta = d.querySelector('textarea'); ta.value = c.code; ta.rows = Math.min(18, c.code.split('\n').length + 1);
    var run = function () { runCell(d, c); };
    d.querySelector('button').onclick = run;
    ta.onkeydown = function (ev) { if (ev.key === 'Enter' && ev.shiftKey) { ev.preventDefault(); run(); } };
    xBox.appendChild(d); runCell(d, c);
  });
}
function runCell(d, c) {
  var o = d.querySelector('.out'); o.innerHTML = '<b>OUTPUT</b>';
  if (d.querySelector('textarea').value.trim() !== c.code.trim()) {
    var n = document.createElement('p'); n.className = 'note';
    n.textContent = 'Code was edited. This is the saved output of the original code; the page cannot run Python itself.'; o.appendChild(n);
  }
  if (!c.out.length) { var p = document.createElement('p'); p.className = 'none'; p.textContent = 'No output for this cell.'; o.appendChild(p); return; }
  c.out.forEach(function (r) {
    if (r.t === 'img') { var im = document.createElement('img'); im.alt = 'Plot output'; im.src = 'data:image/png;base64,' + r.v; o.appendChild(im); }
    else { var pr = document.createElement('pre'); pr.textContent = r.v; o.appendChild(pr); }
  });
}
document.getElementById('xAll').onclick = function () { xBox.querySelectorAll('.cell').forEach(function (d, i) { runCell(d, EXPS[xCur[0]].secs[xCur[1]].cells[i]); }); };
document.getElementById('xReset').onclick = function () { showExp(xCur[0], xCur[1]); };
